%[text] # Ship Optimization
%[text] Find valid subfleets to start off global optimization with decent feasible initital guesses
%%
AU = 1.49579151285e8;
mu_star = 1.32712440018e11; % [km3 / s2]
l_star = AU; % [km] one AU
m_star = 3000; % [kg] - max initial ship mass
a_star = mu_star / l_star ^ 2; % [km / s2]
t_star = sqrt(l_star ^ 3 / mu_star);
v_star = sqrt(mu_star/l_star);
year_to_sec = 86400.0 * 365.25;

mu = 1;
%%
N_ship = 33; % Number of ships wanted
m_mined_avg = log(N_ship / 2) / 0.004 % [kg] %[output:54ef73f4]
m_miner = 40 / m_star % [] every miner is 40 kg %[output:4d6f5c89]
avg_ast_per_ship = 10;
m_dry = 500; % [kg]
m_prop = 1 - m_miner * avg_ast_per_ship - m_dry / m_star %[output:027e5175]
m_ast_mined_avg = m_mined_avg / avg_ast_per_ship %[output:91747fbd]
mf_min = (m_dry + m_mined_avg) / m_star %[output:0d22990b]
%%
%[text] ## Scoring Parameters
%[text] Score is weighted total mass in kg
mining_rate = 10; % [kg / yr]
avg_mining_yr = m_mined_avg / mining_rate / avg_ast_per_ship %[output:0344da91]
%%
ast_data = importdata('GTOC12_Asteroids_Data.txt');
offset = 2;
ast.a = ast_data.data(:, offset + 1);
ast.e = ast_data.data(:, offset + 2);
ast.inc = ast_data.data(:, offset + 3);
ast.Omega = ast_data.data(:, offset + 4);
ast.omega = ast_data.data(:, offset + 5);
ast.M0 = ast_data.data(:, offset + 6);
%%
ast_i = 1:60000;
ast_filter = (ast.a < 2.8) & (ast.a > 2.6) & (ast.e < 0.15) & (ast.e > 0.06) & (ast.inc < 6) & (ast.inc > 0);
ast_filtered_i = ast_i(ast_filter);
%%
size(ast_filtered_i) %[output:73eda2c4]
%%
%[text] ## Starting Asteroid
%[text] Pick from Earth-\>Ast database
EA_dataset = {};
EA_dataset{1} = load("dataset_EA_1p3ToF_0yr.mat").dataset;
EA_t0 = 0; % [yr]
EA_tf = 1.3; % [yr]
EA_m0 = 1;
EA_dataset{1}.ID2 = EA_dataset{1}.IDs;
EA_dataset{1}.ID2_unique = EA_dataset{1}.IDs;
EA_dataset{1}.mf = rockeq_dV_to_dm(EA_dataset{1}.dV_lowthrust * v_star, EA_m0);
EA_dataset{1}.mf_avg = rockeq_dV_to_dm(EA_dataset{1}.dV_lowthrust * v_star, EA_m0);
EA_dataset{1}.paths = [zeros(size(EA_dataset{1}.IDs)); EA_dataset{1}.IDs];
%%
ast_data = importdata('GTOC12_Asteroids_Data.txt');
offset = 2;

ast.a = ast_data.data(:, offset + 1);
ast.e = ast_data.data(:, offset + 2);
ast.inc = deg2rad(ast_data.data(:, offset + 3));
ast.Omega = (ast_data.data(:, offset + 4));
ast.omega = (ast_data.data(:, offset + 5));
ast.M0 = (ast_data.data(:, offset + 6));
ast.L0 = wrapTo360(ast.M0 + ast.Omega + ast.omega);

scatter(ast.a, ast.L0); hold on
scatter(ast.a(EA_dataset{1}.ID2), ast.L0(EA_dataset{1}.ID2)); hold off
%%
%[text] ## Ending Asteroid
%[text] Pick from Ast-\>Earth database
AE_dataset = {};
AE_t0 = {};
AE_tf = {};
AE_mf_ast_mass = {};
AE_dataset{1}{1} = load("dataset_AE_1p0ToF_14p0yr_0p40mf_2.mat").dataset;
AE_t0{1} = 14; % [yr]
AE_tf{1} = 15; % [yr]
AE_dataset{1}{1}.ID1 = AE_dataset{1}{1}.IDs;
AE_dataset{1}{1}.ID1_unique = AE_dataset{1}{1}.IDs;
AE_dataset{1}{1}.m0 = reshape(AE_dataset{1}{1}.m0, 1, []);
AE_dataset{1}{1}.m0_avg = reshape(AE_dataset{1}{1}.m0, 1, []);
AE_mf_ast_mass{1} = (AE_dataset{1}{1}.mf - m_dry / m_star) * m_star;

AE_dataset{2}{1} = load("dataset_AE_0p8ToF_14p2yr_0p40mf.mat").dataset;
AE_t0{2} = 14.2; % [yr]
AE_tf{2} = 15; % [yr]
AE_dataset{2}{1}.ID1 = AE_dataset{2}{1}.IDs;
AE_dataset{2}{1}.ID1_unique = AE_dataset{2}{1}.IDs;
AE_dataset{2}{1}.m0 = reshape(AE_dataset{2}{1}.m0, 1, []);
AE_dataset{2}{1}.m0_avg = reshape(AE_dataset{2}{1}.m0, 1, []);
AE_mf_ast_mass{2} = (AE_dataset{2}{1}.mf - m_dry / m_star) * m_star;

AE_dataset{3}{1} = load("dataset_AE_1p0ToF_13p6yr_0p40mf.mat").dataset;
AE_t0{3} = 13.6; % [yr]
AE_tf{3} = 14.6; % [yr]
AE_dataset{3}{1}.ID1 = AE_dataset{3}{1}.IDs;
AE_dataset{3}{1}.ID1_unique = AE_dataset{3}{1}.IDs;
AE_dataset{3}{1}.m0 = reshape(AE_dataset{3}{1}.m0, 1, []);
AE_dataset{3}{1}.m0_avg = reshape(AE_dataset{3}{1}.m0, 1, []);
AE_mf_ast_mass{3} = (AE_dataset{3}{1}.mf - m_dry / m_star) * m_star;

AE_dataset{4}{1} = load("dataset_AE_1p0ToF_13p8yr_0p40mf.mat").dataset;
AE_t0{4} = 13.8; % [yr]
AE_tf{4} = 14.8; % [yr]
AE_dataset{4}{1}.ID1 = AE_dataset{4}{1}.IDs;
AE_dataset{4}{1}.ID1_unique = AE_dataset{4}{1}.IDs;
AE_dataset{4}{1}.m0 = reshape(AE_dataset{4}{1}.m0, 1, []);
AE_dataset{4}{1}.m0_avg = reshape(AE_dataset{4}{1}.m0, 1, []);
AE_mf_ast_mass{4} = (AE_dataset{4}{1}.mf - m_dry / m_star) * m_star;

AE_dataset{5}{1} = load("dataset_AE_1p2ToF_13p8yr_0p40mf.mat").dataset;
AE_t0{5} = 13.8; % [yr]
AE_tf{5} = 15; % [yr]
AE_dataset{5}{1}.ID1 = AE_dataset{5}{1}.IDs;
AE_dataset{5}{1}.ID1_unique = AE_dataset{5}{1}.IDs;
AE_dataset{5}{1}.m0 = reshape(AE_dataset{5}{1}.m0, 1, []);
AE_dataset{5}{1}.m0_avg = reshape(AE_dataset{5}{1}.m0, 1, []);
AE_mf_ast_mass{5} = (AE_dataset{5}{1}.mf - m_dry / m_star) * m_star;
%%
load_lambert(); %[output:79681487] %[output:3cfeb9f5] %[output:76d12bf8]
%%
%[text] ## Branch out from start and look at possible asteroids
ToF_start = 0.6; % [yr]

t1 = tic();
for i = 9 : 9 %[output:group:22dec4a0]
    [EA_dataset{i + 1}] = Asteroid2Asteroid_lambert_batch_func_array(EA_dataset{i}.ID2_unique, 1:60000, EA_dataset{i}.mf_avg - m_miner, (EA_tf + ToF_start * (i - 1)), ToF_start, EA_dataset{i}.paths, thrust_frac = 0.35, target_ID1_batch_size = 3000); %[output:8541e180] %[output:574a82c9]
    fprintf(sprintf("Completed Segment %g: %g Valid Transfers with %.3f avg mf\n", i, numel(EA_dataset{i + 1}.dV_surrogate), mean(EA_dataset{i + 1}.mf)))
end %[output:group:22dec4a0]
lambert_time = toc(t1)
%%
total_lambert = 0; 

for i = 2 : numel(EA_dataset)
    total_lambert = total_lambert + EA_dataset{i}.num_lambert;
end
total_lambert %[output:9e7d2fe2]
lambert_time / total_lambert %[output:4f88a367]
