for i = 1 : numel(EA_dataset)
    histogram(EA_dataset{i}.mf, Normalization="pdf", DisplayName="Segment " + i); hold on; %[output:74fd07d0]
    xline(mean(EA_dataset{i}.mf), DisplayName = "", HandleVisibility="off")
end
