%[text] ## Find only routes that get from Earth to the last segment
EA_routes = zeros([numel(EA_dataset{end}.ID2), numel(EA_dataset)]);
EA_routes_dV = zeros([numel(EA_dataset{end}.ID2), numel(EA_dataset)]);
EA_routes(:, end) = EA_dataset{end}.ID2;
EA_routes_dV(:, end) = EA_dataset{end}.dV_surrogate;
last_ID_i = EA_dataset{end}.ID1_i;
for i = numel(EA_dataset) : -1 : 2
    EA_routes(:,  i - 1) = EA_dataset{i - 1}.ID2(last_ID_i);
    if i ~= 2
        EA_routes_dV(:,  i - 1) = EA_dataset{i - 1}.dV_surrogate(last_ID_i);
        last_ID_i = EA_dataset{i - 1}.ID1_i(last_ID_i);
    else
        EA_routes_dV(:,  i - 1) = EA_dataset{i - 1}.dV_lowthrust(last_ID_i);
    end
end
